cypress_script:
describe('Accordion Functionality', () => {
  it('should expand the What is Lorem Ipsum section', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.url().should('eq', 'https://demoqa.com/accordian');
  });

  it('should not change URL when clicking on an already expanded section', () => {
    cy.visit('https://demoqa.com/accordian');
    cy.get('.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.get('.accordion-button').contains('What is Lorem Ipsum?').click();
    cy.url().should('eq', 'https://demoqa.com/accordian');
  });
});

playwright_script:
import { test } from '@playwright/test';

test.describe('Accordion Functionality', () => {
  test('should expand the What is Lorem Ipsum section', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await page.waitForURL('https://demoqa.com/accordian');
  });

  test('should not change URL when clicking on an already expanded section', async ({ page }) => {
    await page.goto('https://demoqa.com/accordian');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await page.click('button.accordion-button:has-text("What is Lorem Ipsum?")');
    await page.waitForURL('https://demoqa.com/accordian');
  });
});
